class stringx {
    char *chars;
    void *my_buf;
public:
    stringx();
    stringx(const stringx &);
    stringx(const char *, int = -1);
    ~stringx();
    stringx &operator=(const stringx &);
};
stringx operator+(const stringx &, const stringx &);
stringx operator+(const stringx &, const char *);

struct entity { void load_anim(const stringx &) const; };
struct graphical_system { char pad[0xd4]; int multiplayer; int multi_1; };
struct manager_layout { char pad[8]; graphical_system *gms; };
struct SurferTrick {
    int trick_id;
    int anim_id;
    int board_anim_id;
    int flags;
    int IK_flags;
    int trickbook_type;
    int trick_type;
    unsigned char button1, button2, button3;
    char button1_string[16];
    char button2_string[16];
    char button3_string[16];
    int Time;
    int Points;
};
struct TrickBookFrontEnd { static bool TrickOK(int); };
bool file_finder_exists(const stringx &, const stringx &, stringx * = 0);
extern SurferTrick GTrickList[95];
extern stringx g_surfer_anims[];
extern stringx g_board_anims[];

enum { TRICK_NUM = 95, SURFER_ANIM_NULL = -1, BOARD_ANIM_NULL = -1,
       SURFER_ANIM_PLACEHOLDER = 0, BOARD_ANIM_ZERO = 0 };

class FEEntityManager {
    entity *surfer_ent;
    char pad0[48];
    manager_layout *manager;
    char pad1[348];
    entity *board;
    char pad2[244];
    int tricks_loaded;
public:
    void LoadBoard(int, int);
    void LoadTricks();
};

void FEEntityManager::LoadTricks()
{
	if(tricks_loaded) return;

	// I'll need the board, but more importantly, I need the aux stash loaded
	if(manager->gms->multiplayer && !manager->gms->multi_1)
		LoadBoard(1,0);
	else
		LoadBoard(0,0);

	stringx anim_dir = "characters\\COMMON\\ANIMATIONS\\";
	stringx surfer_anim = "";
	stringx board_anim = "";

	entity* cur_surf = surfer_ent;
	if(cur_surf)
	{
		// currently my idle anim
		cur_surf->load_anim(anim_dir+"ALL_TRK_TUBE_FS_1");
		for(int i=0; i<TRICK_NUM; i++)
		{
			if(TrickBookFrontEnd::TrickOK(i))
			{
				SurferTrick* st = &(GTrickList[i]);
				if( st->anim_id != SURFER_ANIM_NULL )
				{
					surfer_anim = anim_dir+g_surfer_anims[st->anim_id];
					if(file_finder_exists(surfer_anim, ".ANMX"))
						cur_surf->load_anim(surfer_anim);
					else
						g_surfer_anims[st->anim_id] = g_surfer_anims[SURFER_ANIM_PLACEHOLDER];
				}

				if( st->board_anim_id != BOARD_ANIM_NULL )
				{
					board_anim = anim_dir+g_board_anims[st->board_anim_id];
					if(file_finder_exists(board_anim, ".ANMX"))
						board->load_anim(board_anim);
					else
						g_board_anims[st->board_anim_id] = g_board_anims[BOARD_ANIM_ZERO];
				}
			}
		}
	}
	tricks_loaded = true;
}
